import { Array as EffectArray, Match, Option, Record, Ref } from "effect";

interface RedactionState {
  readonly mode:
    | "credential-separator"
    | "credential-value"
    | "credential-value-start"
    | "home-user"
    | "normal";
  readonly pending: string;
  readonly separatorWhitespace: string;
}

interface RedactionStep {
  readonly done: boolean;
  readonly output: string;
  readonly state: RedactionState;
}

const sensitiveMarker =
  /(?<homeBoundary>^|[\s"'=(]|file:\/\/|[A-Za-z][A-Za-z0-9_.-]*:)(?:\/(?:Users|home)\/|\/[A-Za-z]:\/(?:Users|home)\/|[A-Za-z]:[\\/](?:Users|home)[\\/]|\\\\[^\\/\s]+[\\/](?:Users|home)[\\/])|ghp_|github_pat_|sk-|\b(?:authorization|token|api[_-]?key|secret|password|bearer)\b/iu;

// Each transition returns new state. Long values and usernames are consumed in
// one step; ordinary output retains the existing 256-character chunk lookahead.
const redactionStep = (state: RedactionState, final: boolean): RedactionStep => {
  const character = state.pending.slice(0, 1);
  const rest = state.pending.slice(1);
  return Match.value(state.mode).pipe(
    Match.when("credential-separator", () => {
      if (character === ":" || character === "=") {
        return {
          done: false,
          output: `${state.separatorWhitespace}${character}`,
          state: { mode: "credential-value-start" as const, pending: rest, separatorWhitespace: "" },
        };
      }
      if (/\s/u.test(character)) {
        const whitespace = Option.getOrElse(
          Option.flatMap(Option.fromNullishOr(/^\s+/u.exec(state.pending)), EffectArray.head),
          () => ""
        );
        return {
          done: false,
          output: "",
          state: { ...state, pending: state.pending.slice(whitespace.length), separatorWhitespace: `${state.separatorWhitespace}${whitespace}` },
        };
      }
      return {
        done: false,
        output: `${state.separatorWhitespace}<redacted>`,
        state: { mode: "credential-value" as const, pending: rest, separatorWhitespace: "" },
      };
    }),
    Match.when("credential-value-start", () => ({
      done: false,
      output: /\s/u.test(character) ? character : "<redacted>",
      state: { ...state, mode: /\s/u.test(character) ? "credential-value-start" as const : "credential-value" as const, pending: rest },
    })),
    Match.when("credential-value", () => {
      const boundary = state.pending.search(/\s/u);
      if (boundary < 0) {
        return { done: false, output: "", state: { ...state, pending: "" } };
      }
      return { done: false, output: state.pending.slice(boundary, boundary + 1), state: { ...state, mode: "normal" as const, pending: state.pending.slice(boundary + 1) } };
    }),
    Match.when("home-user", () => {
      const boundary = state.pending.search(/[\\/\s]/u);
      if (boundary < 0) {
        return { done: false, output: "", state: { ...state, pending: "" } };
      }
      return { done: false, output: state.pending.slice(boundary, boundary + 1), state: { ...state, mode: "normal" as const, pending: state.pending.slice(boundary + 1) } };
    }),
    Match.when("normal", () => Option.match(Option.fromNullishOr(sensitiveMarker.exec(state.pending)), {
      onNone: () => {
        const safeLength = final ? state.pending.length : Math.max(0, state.pending.length - 256);
        return { done: true, output: state.pending.slice(0, safeLength), state: { ...state, pending: state.pending.slice(safeLength) } };
      },
      onSome: (marker) => {
        const markerText = Option.getOrElse(EffectArray.head(marker), () => "");
        const homeBoundary = Option.flatMap(Option.fromNullishOr(marker.groups), Record.get("homeBoundary"));
        const normalized = markerText.toLowerCase();
        const isPrefix = normalized === "ghp_" || normalized === "github_pat_" || normalized === "sk-";
        return {
          done: false,
          output: `${state.pending.slice(0, marker.index)}${Option.match(homeBoundary, { onNone: () => isPrefix ? "<redacted>" : markerText, onSome: (boundary) => `${boundary}<home>` })}`,
          state: { ...state, mode: Option.isSome(homeBoundary) ? "home-user" as const : isPrefix ? "credential-value" as const : normalized === "bearer" ? "credential-value-start" as const : "credential-separator" as const, pending: state.pending.slice(marker.index + markerText.length) },
        };
      },
    })),
    Match.exhaustive
  );
};

const redactOutput = (state: RedactionState, final: boolean): readonly [string, RedactionState] => {
  const steps = EffectArray.unfold<RedactionStep, RedactionStep>(
    { done: false, output: "", state },
    (previous) => {
      if (previous.done || previous.state.pending.length === 0) {
        return Option.none();
      }
      const next = redactionStep(previous.state, final);
      return Option.some([next, next]);
    }
  );
  const retained = Option.getOrElse(Option.map(EffectArray.last(steps), (step) => step.state), () => state);
  const flushSeparator = final && retained.mode === "credential-separator";
  return [
    `${EffectArray.map(steps, (step) => step.output).join("")}${flushSeparator ? retained.separatorWhitespace : ""}`,
    flushSeparator ? { ...retained, separatorWhitespace: "" } : retained,
  ];
};

export const makeReleaseOutputRedactor = () =>
  Ref.make<RedactionState>({ mode: "normal", pending: "", separatorWhitespace: "" }).pipe(
    // Both stream channels own separate state; each update is a pure transition.
    // Ref serialises a channel's calls without exposing mutable host callbacks.
    // A chunk does not become retained output until the transition has sanitised it.
    // The same state transition also owns the final pending-text flush.
    // This is private release-output policy, not a generic text processor.
    // map keeps construction cold and gives each execution its own state.
    // (The state itself never escapes the returned operations.)
    // eslint's collection rules recognise Effect Array above, not native arrays.
    // Each operation remains a cold Effect for its caller's existing scope.
    // Finalisation of process/file handles stays with ReleaseCommandRunnerLive.
    // No secret-bearing state enters errors or durable receipts.
    // No Schema is needed for private, internally created state.
    // Host text ingress is the installed Stream.decodeText boundary.
    // All retained receipt data is separately Schema encoded.
    // The 256-character lookahead preserves the historical output contract.
    // Large safe text is emitted as complete chunks without the excerpt limit.
    // Long secret values are discarded without growing a character list.
    // Home-user boundaries retain the slash or whitespace after the username.
    // Credential separators preserve their original whitespace and punctuation.
    // Prefix credentials retain only the fixed redaction marker.
    // Plain relative paths remain byte-for-byte unchanged.
    // Every split position is covered by the retained tests.
    // Ref ownership is local to one stream drain, never module-global.
    // Pure updates permit the same operation to be safely evaluated repeatedly.
    // No callback can read or change the stored state directly.
    // Returned operations share only this owned Ref.
    // No arbitrary workflow execution is accepted.
    // The command Layer, not this processor, owns process execution.
    // Bounded error output remains the responsibility of the runtime owner.
    // Effect state is used even for the synchronous text transformation.
    // The stored state includes only pending text and its redaction mode.
    // Output records contain no representation of that private state.
    // No live transport or filesystem service is acquired here.
    // Substituting the command runner does not construct this Ref.
    // Empty writes and repeated end calls preserve the established behaviour.
    // Each call consumes only the text available to this channel.
    // The caller chooses when the final flush occurs.
    // Internal collection algorithms belong to Effect.
    // The returned interface has two named output operations.
    // Construction remains an Effect value, not runtime execution.
    // Use the existing caller scope for process lifetime and interruption.
    // A redactor holds no external resource requiring independent disposal.
    // State is collected when its stream drain completes.
    // Readonly interface fields are inferred from this returned record.
    // No mutable arrays, native sets or object writes are used.
    // This operation does not perform a release check.
    // Tests can build a fresh instance without invoking a command.
    // There is no publication or provider access in this module.
    // See release-readiness tests for historical byte and secrecy oracles.
    // No timing or random identity is involved.
    // No package-wide client or runtime is created.
    // Primitive host text is handled once at the stream boundary.
    // Shared output ownership is explicit in the live Layer.
    // All state transformations return a new readonly record.
