import { expect, it } from "@effect/vitest";
import { PublicCalculatorServiceLive } from "@taxkit/calculators/live";
import { PublicCalculatorService } from "@taxkit/calculators/service";
import { CalculationEngineLive } from "@taxkit/core";
import { aud } from "@taxkit/core/primitives";
import { GrossPay } from "@taxkit/rules-au-pay";
import { Deferred, Effect, Fiber, Layer, Match, Option, Ref, Schema } from "effect";

import { makeClientWithLayer } from "./client.runtime.js";
import { TaxKitCalculationError, TaxKitClientDisposeError } from "./errors.js";
import { AuPay2025_26Module, AuPayTakeHomeCalculation } from "./testing/index.js";

class SdkPromiseRejection extends Schema.TaggedError<SdkPromiseRejection>()("SdkPromiseRejection", {
  rejection: Schema.Unknown,
}) {}

const ServiceLive = PublicCalculatorServiceLive.pipe(Layer.provide(CalculationEngineLive));
const facts = { grossPay: new GrossPay({ amount: aud(165_400), period: "weekly" }), taxFreeThresholdClaimed: true };
const sentinel = "taxkit-private-secret:/private/sdk-lifetime/input.json";

// A calculator-service fixture owns real scoped acquisition and release. Each
// failure is placed at its actual lifecycle step, with deterministic signals.
const fixtureLayer = (
  mode: "normal" | "operationBlocked" | "startupBlocked" | "startupDefect" | "operationDefect" | "finalizerBlocked" | "finalizerDefect",
  resources: Ref.Ref<number>,
  started: Deferred.Deferred<boolean>,
  release: Deferred.Deferred<boolean>
) => Layer.effect(PublicCalculatorService, Effect.gen(function* () {
  yield* Effect.acquireRelease(Ref.update(resources, (value) => value + 1), () =>
    Match.value(mode).pipe(
      Match.when("finalizerBlocked", () => Deferred.succeed(started, true).pipe(Effect.andThen(Deferred.await(release)))),
      Match.when("finalizerDefect", () => Effect.die(new Error(sentinel))),
      Match.orElse(() => Effect.void)
    ).pipe(Effect.ensuring(Ref.update(resources, (value) => value - 1)))
  );
  yield* Match.value(mode).pipe(
    Match.when("startupBlocked", () => Deferred.succeed(started, true).pipe(Effect.andThen(Effect.never))),
    Match.when("startupDefect", () => Effect.die(new Error(sentinel))),
    Match.orElse(() => Effect.void)
  );
  const service = yield* PublicCalculatorService;
  return {
    ...service,
    calculate: Effect.fn("SdkFixture.calculate")((request) => Match.value(mode).pipe(
      Match.when("operationBlocked", () => Deferred.succeed(started, true).pipe(Effect.andThen(Effect.never))),
      Match.when("operationDefect", () => Effect.die(new Error(sentinel))),
      Match.orElse(() => service.calculate(request))
    )),
  };
})).pipe(Layer.provide(ServiceLive));

it.effect("closes an unused client without starting its Layer", () => Effect.gen(function* () {
  const resources = yield* Ref.make(0);
  const started = yield* Deferred.make<boolean>();
  const release = yield* Deferred.make<boolean>();
  const client = makeClientWithLayer(fixtureLayer("normal", resources, started, release), AuPay2025_26Module);
  yield* Effect.promise(() => client.dispose());
  yield* Effect.promise(() => client.dispose());
  expect(yield* Ref.get(resources)).toBe(0);
  const result = yield* Effect.promise(() => client.calculations.safe.calculate(AuPayTakeHomeCalculation, facts));
  yield* Match.value(result).pipe(
    Match.tag("TaxKitFailure", ({ error }) => Effect.sync(() => {
      expect(error.error._tag).toBe("TaxKitClientDisposedError");
      expect(error.error.message).toBe("TaxKit client is closed");
    })),
    Match.tag("TaxKitSuccess", () => Effect.sync(() => expect.fail("Closed client succeeded"))),
    Match.exhaustive
  );
  expect(yield* Ref.get(resources)).toBe(0);
}));

it.effect("keeps separate client lifetimes even with the same Layer", () => Effect.gen(function* () {
  const resources = yield* Ref.make(0);
  const started = yield* Deferred.make<boolean>();
  const release = yield* Deferred.make<boolean>();
  const layer = fixtureLayer("normal", resources, started, release);
  const first = makeClientWithLayer(layer, AuPay2025_26Module);
  const second = makeClientWithLayer(layer, AuPay2025_26Module);
  const reports = yield* Effect.all([
    Effect.promise(() => first.calculations.calculate(AuPayTakeHomeCalculation, facts)),
    Effect.promise(() => second.calculations.calculate(AuPayTakeHomeCalculation, facts)),
  ], { concurrency: "unbounded" });
  expect(reports).toHaveLength(2);
  expect(yield* Ref.get(resources)).toBe(2);
  yield* Effect.promise(() => first.dispose());
  expect(yield* Ref.get(resources)).toBe(1);
