it.effect("all overlapping dispose calls await the same finalisers", () => Effect.gen(function* () {
  const resources = yield* Ref.make(0);
  const started = yield* Deferred.make<boolean>();
  const release = yield* Deferred.make<boolean>();
  const client = makeClientWithLayer(fixtureLayer("finalizerBlocked", resources, started, release), AuPay2025_26Module);
  yield* Effect.promise(() => client.calculations.calculate(AuPayTakeHomeCalculation, facts));
  const first = yield* Effect.promise(() => client.dispose()).pipe(Effect.forkChild);
  yield* Deferred.await(started);
