  expect(Option.isNone(Fiber.pollUnsafe(first))).toBe(true);
  expect(Option.isNone(Fiber.pollUnsafe(second))).toBe(true);
  expect(yield* Ref.get(resources)).toBe(1);
  yield* Deferred.succeed(release, true);
