import { Config, Context, Effect, Layer, Schema, SchemaTransformation } from "effect";

import {
  ApiServerConfigError,
  ApiServerConfigSchema,
  ApiServerConfigSourceSchema,
  ApiServerTcpAddressSchema,
} from "./schemas.js";
import type { ApiServerConfigService } from "./schemas.js";

const defaultHost = "127.0.0.1";
const defaultPort = 4000;

export class ApiServerConfig extends Context.Service<ApiServerConfig, ApiServerConfigService>()("@taxkit/api/ServerConfig") {}

const HostEnvironmentValue = Schema.String.pipe(Schema.decodeTo(
  ApiServerConfigSourceSchema.fields.host,
  SchemaTransformation.transform({
    decode: (host) => host.trim() || defaultHost,
    encode: (host) => host,
  })
));

// Config resolves the caller's provider. The live application uses the native
// environment provider; tests substitute it without changing ambient settings.
export const loadApiServerConfig = Config.all({
  host: Config.schema(HostEnvironmentValue, "API_HOST").pipe(Config.withDefault(defaultHost)),
  port: Config.schema(ApiServerConfigSourceSchema.fields.port, "API_PORT").pipe(
    Config.orElse(() => Config.schema(ApiServerConfigSourceSchema.fields.port, "PORT")),
    Config.withDefault(defaultPort)
  ),
}).pipe(
  Effect.mapError(() => new ApiServerConfigError({ operation: "settings" })),
  Effect.map((source) => ApiServerConfigSchema.make({
    address: ApiServerTcpAddressSchema.make({ hostname: source.host, port: source.port }),
  }))
);

export const ApiServerConfigLive = Layer.effect(ApiServerConfig, loadApiServerConfig);
EOF
