        ...Array.filter(Array.fromIterable(response.headers), ([name]) =>
          name !== runtimeProofResponseHeader && name !== runtimeProofIsolateHeader),
        [runtimeProofResponseHeader, String(probe.constructions)],
        [runtimeProofIsolateHeader, probe.isolateId],
      ]);
      return new Response(response.body, { headers, status: response.status, statusText: response.statusText });
    }), { signal: request.signal }
